import { requireUser } from '@/lib/auth';
import { audit } from '@/lib/audit';
import { json, route, HttpError } from '@/lib/http';
import { getPatient } from '@/repos/patients';
import { listForPatient as listAppointments } from '@/repos/appointments';
import { listForUser as listMessages } from '@/repos/messages';
import { listClinicalForPatient } from '@/repos/notes';

/** The signed-in patient's own general record. Excludes psychotherapy notes. */
export const GET = route(async (req) => {
  const user = await requireUser(req);
  if (user.role !== 'patient' || !user.patientId) throw new HttpError(403, 'forbidden');
  const p = await getPatient(user.patientId);
  if (!p) throw new HttpError(404, 'not_found');
  const [appts, msgs, notes] = await Promise.all([
    listAppointments(p.id),
    listMessages(user.id),
    listClinicalForPatient(p.id),
  ]);
  await audit(user, 'export', 'patient', p.id);
  return json({
    patient: {
      id: p.id,
      firstName: p.first_name,
      lastName: p.last_name,
      dateOfBirth: p.date_of_birth,
      email: p.email,
      phone: p.phone,
      mrn: p.mrn,
    },
    appointments: appts.map((a) => ({
      id: a.id,
      startsAt: a.starts_at,
      endsAt: a.ends_at,
      status: a.status,
      visitReason: a.visit_reason,
    })),
    messages: msgs.map((m) => ({
      id: m.id,
      subject: m.subject,
      body: m.body,
      sentAt: m.created_at,
      direction: m.sender_user_id === user.id ? 'sent' : 'received',
    })),
    clinicalNotes: notes.map((n) => ({ id: n.id, createdAt: n.created_at, body: n.body })),
  });
});
EOF
